"""Privacy-preserving Odoo feedback vectors for offline model training.

The payload stores only normalized numeric feature vectors and labels. It does
not contain names, transaction references, amounts, URLs, or Odoo identifiers.
"""

from __future__ import annotations

import base64
import json
import zlib
from typing import Any

_COMPRESSED_FEEDBACK_B64 = (
    ""
)


def load_feedback_document() -> dict[str, Any]:
    compressed = base64.b64decode(_COMPRESSED_FEEDBACK_B64, validate=True)
    raw = zlib.decompress(compressed)
    document = json.loads(raw.decode("utf-8"))

    if not isinstance(document, dict):
        raise ValueError("Odoo feedback corpus must decode to an object.")

    return document
